<?php
declare(strict_types=1);
final class DisbursementDocumentComplianceService
{
 public function __construct(private PDO $pdo){$this->ensureSchema();}
 public function evaluate(array $f):array{$amount=(float)($f['montant_fiche']??0);$advance=!empty($f['is_advance']);$invoiceDeferred=!empty($f['invoice_collection_deferred']);$present=['bci'=>trim((string)($f['code_autorisation_feb']??''))!=='','fne'=>trim((string)($f['facture_reference']??''))!=='','pv'=>trim((string)($f['pv_reception_reference']??''))!==''];$required=['bci'=>true,'fne'=>$amount>250000,'pv'=>!$advance];$missing=[];foreach($required as $key=>$needed)if($needed&&!$present[$key]&&!($key==='fne'&&$invoiceDeferred))$missing[]=$key;$returned=(string)($f['document_completion_status']??'')==='returned';return compact('amount','advance','invoiceDeferred','present','required','missing','returned')+['eligible'=>!$missing&&!$returned];}
 public function assertEligible(array $rows):void{$errors=[];foreach($rows as $f){$s=$this->evaluate($f);if(!$s['eligible'])$errors[]=(string)($f['num_fiche']??'Fiche').' : '.($s['returned']?'retournée au demandeur':'documents manquants ('.strtoupper(implode(', ',$s['missing'])).')');}if($errors)throw new RuntimeException("Certaines fiches ne peuvent pas intégrer le point du jour :\n".implode("\n",$errors));}
 public function setAdvance(string $number,bool $advance,int $userId):void{$s=$this->pdo->prepare('UPDATE fiche_decaissement SET is_advance=:v,document_updated_by=:u,updated_at=NOW() WHERE num_fiche=:n AND COALESCE(decaisse,0)=0');$s->execute(['v'=>$advance?1:0,'u'=>$userId?:null,'n'=>$number]);if(!$s->rowCount())throw new RuntimeException('Fiche introuvable ou déjà décaissée.');}
 public function setInvoiceCollectionDeferred(string $number,bool $deferred,int $userId):void{$s=$this->pdo->prepare('SELECT montant_fiche,facture_reference FROM fiche_decaissement WHERE num_fiche=:n AND COALESCE(decaisse,0)=0 LIMIT 1');$s->execute(['n'=>$number]);$fiche=$s->fetch(PDO::FETCH_ASSOC);if(!$fiche)throw new RuntimeException('Fiche introuvable ou déjà décaissée.');if($deferred&&(float)$fiche['montant_fiche']<=250000)throw new DomainException('Le report de facture est réservé aux fiches de plus de 250 000 FCFA.');if($deferred&&trim((string)($fiche['facture_reference']??''))!=='')throw new DomainException('Une facture est déjà enregistrée sur cette fiche.');$u=$this->pdo->prepare('UPDATE fiche_decaissement SET invoice_collection_deferred=:v,invoice_collection_deferred_at=:at,invoice_collection_deferred_by=:by,document_updated_by=:by,updated_at=NOW() WHERE num_fiche=:n AND COALESCE(decaisse,0)=0');$u->execute(['v'=>$deferred?1:0,'at'=>$deferred?date('Y-m-d H:i:s'):null,'by'=>$userId?:null,'n'=>$number]);}
 public function returnToRequester(string $number,string $reason,int $userId):void{if(trim($reason)==='')throw new DomainException('Précisez les documents attendus.');$s=$this->pdo->prepare("UPDATE fiche_decaissement SET document_completion_status='returned',document_completion_reason=:r,document_returned_at=NOW(),document_returned_by=:u,document_updated_by=:u,updated_at=NOW() WHERE num_fiche=:n AND COALESCE(decaisse,0)=0");$s->execute(['r'=>trim($reason),'u'=>$userId?:null,'n'=>$number]);if(!$s->rowCount())throw new RuntimeException('Fiche introuvable ou déjà décaissée.');try{$q=$this->pdo->prepare('SELECT created_by_user_id FROM fiche_decaissement WHERE num_fiche=:n');$q->execute(['n'=>$number]);$recipient=(int)$q->fetchColumn();if($recipient>0){$n=$this->pdo->prepare("INSERT INTO system_notifications(created_at,event_key,sub_key,title,message,link_url,recipient_user_id,channels_json,payload_json) VALUES(NOW(),'fiche_document_completion','returned',:title,:message,:link,:uid,'[\"system\"]','{}')");$n->execute(['title'=>'Complément documentaire requis · '.$number,'message'=>trim($reason),'link'=>'/decaissement/mes_complements_documentaires.php','uid'=>$recipient]);}}catch(Throwable $ignored){}}
 private function ensureSchema():void{$c=$this->pdo->query('SHOW COLUMNS FROM fiche_decaissement')->fetchAll(PDO::FETCH_COLUMN,0)?:[];$a=[];if(!in_array('is_advance',$c,true))$a[]="ADD COLUMN is_advance TINYINT(1) NOT NULL DEFAULT 0 AFTER facture_reference";if(!in_array('invoice_collection_deferred',$c,true))$a[]="ADD COLUMN invoice_collection_deferred TINYINT(1) NOT NULL DEFAULT 0 AFTER is_advance";if(!in_array('invoice_collection_deferred_at',$c,true))$a[]="ADD COLUMN invoice_collection_deferred_at DATETIME NULL AFTER invoice_collection_deferred";if(!in_array('invoice_collection_deferred_by',$c,true))$a[]="ADD COLUMN invoice_collection_deferred_by INT NULL AFTER invoice_collection_deferred_at";if(!in_array('document_completion_status',$c,true))$a[]="ADD COLUMN document_completion_status ENUM('complete','returned','resubmitted') NOT NULL DEFAULT 'complete' AFTER invoice_collection_deferred_by";if(!in_array('document_completion_reason',$c,true))$a[]="ADD COLUMN document_completion_reason TEXT NULL AFTER document_completion_status";if(!in_array('document_returned_at',$c,true))$a[]="ADD COLUMN document_returned_at DATETIME NULL AFTER document_completion_reason";if(!in_array('document_returned_by',$c,true))$a[]="ADD COLUMN document_returned_by INT NULL AFTER document_returned_at";if(!in_array('document_updated_by',$c,true))$a[]="ADD COLUMN document_updated_by INT NULL AFTER document_returned_by";if($a)$this->pdo->exec('ALTER TABLE fiche_decaissement '.implode(',',$a));}
}
